#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Class definition for one of Velocity's REST api methods.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import re
import json

import utility


class CMethod(object):
    def __init__(self, method, query_type):
        self.method = method
        self.query_type = query_type
        self.url = None
        self.required_parameters = []

    def __str__(self):
        func = {}
        func['url'] = self.url
        func['query_type'] = self.query_type
        func['required_parameters'] = self.required_parameters
        return json.dumps(func)

    def _get_raw_url(self):
        paragraphs = self.method.find_all('p')
        for paragraph in paragraphs:
            if 'full url' in paragraph.text.lower():
                url = paragraph.text.split(' ')[-1]
        try:
            url = url
        except NameError:
            url = self.method.find('code').text.split('?')[0]
        return url

    def _export_params_from_url(self, url):
        if '{' in url:
            params = re.findall(r"\{(.*?)\}", url)
            for param in params:
                url = url.replace(param, '')
            return [utility.camel_case_to_snake_case(x) for x in params], url
        return [], url

    def _parse_url(self, url, params):
        if params:
            url = url + "'.format({})".format(', '.join(params))
        else:
            url += "'"
        url = url.replace('/ito/', 'ito/')
        url = url.replace('/velocity/', '')
        url = "'" + url
        return url

    def _get_url_and_params(self):
        url = self._get_raw_url()
        params, url = self._export_params_from_url(url)
        url = self._parse_url(url, params)
        return url, params

    def parse(self):
        self.url, self.required_parameters = self._get_url_and_params()
